```yaml
name: Comment Artifacts

on:
  workflow_run:
    workflows: ["Test Build"]
    types:
      - completed

jobs:
  comment-artifacts:
    if: ${{ github.event.workflow_run.conclusion == 'success' }}
    runs-on: ubuntu-latest
    steps:
      - name: Download artifacts
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const runId = context.payload.workflow_run.id;

            // Get the workflow run details
            const workflowRun = await github.rest.actions.getWorkflowRun({
              owner,
              repo,
              run_id: runId
            });

            const commitSha = workflowRun.data.head_sha;

            // Find PR associated with this commit
            const prResponse = await github.rest.repos.listPullRequestsAssociatedWithCommit({
              owner,
              repo,
              commit_sha: commitSha
            });

            if (prResponse.data.length === 0) {
              console.log("No PR found for this commit");
              return;
            }

            const prNumber = prResponse.data[0].number;

            // Get artifacts
            const artifactsResponse = await github.rest.actions.listWorkflowRunArtifacts({
              owner,
              repo,
              run_id: runId
            });

            const artifacts = artifactsResponse.data.artifacts;

            // Filter for ISO artifacts
            const isoArtifacts = artifacts.filter(artifact => 
              artifact.name.toLowerCase().includes('iso')
            );

            if (isoArtifacts.length === 0) {
              console.log("No ISO artifacts found");
              return;
            }

            // Create comment body
            let commentBody = "## 📦 ISO Artifacts\n\n";
            commentBody += "Here are the ISO artifacts built from this pull request:\n\n";

            for (const artifact of isoArtifacts) {
              commentBody += `- [${artifact.name}](${artifact.browser_download_url})\n`;
            }

            commentBody += "\n> ⚠️ These artifacts are for testing purposes only.\n";

            // Check if comment already exists
            const commentsResponse = await github.rest.issues.listComments({
              owner,
              repo,
              issue_number: prNumber
            });

            const existingComment = commentsResponse.data.find(comment => 
              comment.body.includes("## 📦 ISO Artifacts")
            );

            if (existingComment) {
              // Update existing comment
              await github.rest.issues.updateComment({
                owner,
                repo,
                comment_id: existingComment.id,
                body: commentBody
              });
            } else {
              // Create new comment
              await github.rest.issues.createComment({
                owner,
                repo,
                issue_number: prNumber,
                body: commentBody
              });
            }
